success:"2XX",missing:"404",redirect:"3XX",error:"5XX"};def initialize(code_or_name)if code_or_name.is_a?(Symbol);@name=code_or_name;@code=code_from_name(code_or_name);else @name=name_from_code(code_or_name);@code=code_or_name;end;raise ArgumentError,"Invalid response name: #{name}" if @code.nil?;raise ArgumentError,"Invalid response code: #{code}" if @name.nil?;end;def code_and_name;"#{code}: #{name}";end;private;def code_from_name(name)GENERIC_RESPONSE_CODES[name]||ActionDispatch::Response.rack_status_code(name);end;def name_from_code(code)GENERIC_RESPONSE_CODES.invert[code]||Rack::Utils::HTTP_STATUS_CODES[code];end;end;end
